use std::fs;use std::io;use std::num::ParseIntError;
#[derive(Debug)]enum AppError{Io(io::Error),Parse(ParseIntError),NotFound(String)}
impl From<io::Error> for AppError{fn from(e:io::Error)->Self{AppError::Io(e)}}
impl From<ParseIntError> for AppError{fn from(e:ParseIntError)->Self{AppError::Parse(e)}}
impl std::fmt::Display for AppError{fn fmt(&self,f:&mut std::fmt::Formatter)->std::fmt::Result{match self{Self::Io(e)=>write!(f,"IO error: {e}"),Self::Parse(e)=>write!(f,"Parse error: {e}"),Self::NotFound(s)=>write!(f,"Not found: {s}")}}}
fn read_age_from_file(path:&str)->Result<u32,AppError>{let content=fs::read_to_string(path)?;let age:u32=content.trim().parse()?;if age>150{return Err(AppError::NotFound("Invalid age".to_string()))};Ok(age)}

fn main(){println!("{}",read_age_from_file("age.txt").unwrap());}

